insert into public.catalog_meals (slug, name, category, tags, popular, servings, sort_order, image_path, prep_steps)
select slug, name, category, tags::public.meal_tag[], popular, servings, sort_order,
       -- Placeholder until the photo set lands; the app shows an ingredient-icon tile when missing.
       'catalog/' || slug || '.jpg',
       -- Lead-time prep steps derived from the tags (spec: thaw 24 h, slow cooker start 8 h).
       (case when 'thaw_first' = any (tags::text[])
             then '[{"step": "Move the meat to the fridge to thaw", "lead_hours": 24}]'::jsonb
             else '[]'::jsonb end)
       || (case when 'slow_cooker' = any (tags::text[])
             then '[{"step": "Start the slow cooker", "lead_hours": 8}]'::jsonb
             else '[]'::jsonb end)
from dishes
on conflict (slug) do update set
  name = excluded.name,
  category = excluded.category,
  tags = excluded.tags,
  popular = excluded.popular,
  servings = excluded.servings,
  sort_order = excluded.sort_order,
  image_path = excluded.image_path,
  prep_steps = excluded.prep_steps;

delete from public.catalog_ingredients;

insert into public.catalog_ingredients (catalog_meal_id, name, category, quantity_text, position)
select m.id,
       split_part(i.entry, '|', 1),
       split_part(i.entry, '|', 2)::public.item_category,
       nullif(split_part(i.entry, '|', 3), ''),
       i.ord
